from __future__ import annotations

from typing import Iterable, List, Sequence, Tuple

from .models import SceneObject

Vector3 = Tuple[float, float, float]


def build_scene_obj(objects: Iterable[SceneObject]) -> str:
    lines: List[str] = [
        "# Generated by cosmos-robot-simgen",
        "mtllib scene.mtl",
    ]
    vertex_offset = 1
    for obj in objects:
        mesh = _box_mesh(obj.position, obj.size)
        lines.append(f"o {obj.object_id}")
        lines.extend(f"v {x:.6f} {y:.6f} {z:.6f}" for x, y, z in mesh["vertices"])
        lines.extend(f"f {a + vertex_offset} {b + vertex_offset} {c + vertex_offset}" for a, b, c in mesh["faces"])
        vertex_offset += len(mesh["vertices"])
    lines.append("")
    return "\n".join(lines)


def build_scene_mtl(objects: Iterable[SceneObject]) -> str:
    lines: List[str] = ["# Generated by cosmos-robot-simgen"]
    for obj in objects:
        red, green, blue = _hex_to_rgb(obj.color)
        lines.extend(
            [
                f"newmtl {obj.object_id}",
                f"Kd {red:.4f} {green:.4f} {blue:.4f}",
                "Ka 0.1000 0.1000 0.1000",
                "Ks 0.0500 0.0500 0.0500",
                "",
            ]
        )
    return "\n".join(lines)


def _box_mesh(center: Vector3, size: Vector3) -> dict:
    cx, cy, cz = center
    sx, sy, sz = (size[0] / 2.0, size[1] / 2.0, size[2] / 2.0)
    vertices = [
        (cx - sx, cy - sy, cz - sz),
        (cx + sx, cy - sy, cz - sz),
        (cx + sx, cy + sy, cz - sz),
        (cx - sx, cy + sy, cz - sz),
        (cx - sx, cy - sy, cz + sz),
        (cx + sx, cy - sy, cz + sz),
        (cx + sx, cy + sy, cz + sz),
        (cx - sx, cy + sy, cz + sz),
    ]
    faces = [
        (0, 1, 2),
        (0, 2, 3),
        (4, 6, 5),
        (4, 7, 6),
        (0, 4, 5),
        (0, 5, 1),
        (1, 5, 6),
        (1, 6, 2),
        (2, 6, 7),
        (2, 7, 3),
        (3, 7, 4),
        (3, 4, 0),
    ]
    return {"vertices": vertices, "faces": faces}


def _hex_to_rgb(value: str) -> Sequence[float]:
    cleaned = value.strip().lstrip("#")
    if len(cleaned) != 6:
        return (0.5, 0.5, 0.5)
    try:
        return tuple(int(cleaned[i : i + 2], 16) / 255.0 for i in (0, 2, 4))
    except ValueError:
        return (0.5, 0.5, 0.5)
